set-payload.value:
#[{
  status: "IGNORE_DUPLICATE",
  reason: "Event ID has already been processed"
}]

#[{
  status: "IGNORE_STALE",
  reason: "Incoming event version is not newer than stored version"
}]

#[{
    status: "REJECTED",
    reason: "Available stock cannot be negative",
    sku: payload.sku,
    locationCode: payload.locationCode
}]

#[{
    status: "IGNORED_STALE",
    eventId: vars.inventoryEvent.event.eventId,
    reason: "Event is no longer newer than stored inventory"
}]

#[{
    status: "VERSION_CONFLICT",
    eventId: vars.inventoryEvent.event.eventId,
    reason: "Maximum concurrency retries exceeded"
}]

#[{
    status: "INVALID_STOCK",
    eventId: vars.inventoryEvent.event.eventId,
    reason: "Recalculated stock is invalid"
}]
